{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "तो Rosidul जी आपकी Nokia 5800 refurbished mobile की request IndiaMART पर raised है।"
    },
    {
      "i": 1,
      "speaker": "bot",
      "text": "बस उसी के लिए कुछ details confirm करनी थी।"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "चलिए अब RAM के बारे में बात कर लेते हैं।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए 8 GB या कुछ और?"
    },
    {
      "i": 5,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "ओ Nokia का hi to बोलते हैं ना?"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "जी आप Nokia 5800 refurbished mobile की बात कर रहे हैं।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "तो बताइए RAM में क्या prefer करेंगे 8 GB, 4 GB या कोई और?"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "कोई दिक्कत नहीं।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "ठीक है।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "क्या आप इस product के बारे में कोई और details या specification share करना चाहेंगे?"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "जी जी।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "आपकी details note कर ली गई हैं और जल्द ही एक seller आपसे contact करेंगे।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    }
  ]
}
